	@Test
	void sampledViewReportsCenterCompleteness(@TempDir Path frontierDirectory) throws Exception {
		double inclusionProbability = 0.5d;
		long survivor = nextCenter(true, 0L, inclusionProbability);
		long absentNonSurvivor = nextCenter(false, 0L, inclusionProbability);
		long heavyNonSurvivor = nextCenter(false, absentNonSurvivor, inclusionProbability);
		long reverseHeavyNonSurvivor = nextCenter(false, heavyNonSurvivor, inclusionProbability);
		FrontierPayloadDescriptor descriptor = descriptor();
		FrontierQueryIndex.Builder builder = FrontierQueryIndex.builder(
				frontierDirectory, identity(), descriptor, BUDGET_BYTES, NioFrontierFileOps.INSTANCE);
		builder.accept(1, 1, 0, true, false, survivor, 101L, 21L, 0L, 2.0d, inclusionProbability, 0L);
		builder.accept(1, 1, 0, true, true, heavyNonSurvivor, 101L, 22L, 0L, 1.0d, 1.0d, 0L);
		builder.accept(2, 1, 0, true, true, reverseHeavyNonSurvivor, 101L, 23L, 0L, 1.0d, 1.0d, 0L);
		FrontierQueryIndex index = builder.finish(inclusionProbability, false);
		FrontierQueryIndexView view;
		try {
			view = new FrontierQueryIndexView(identity(), List.of(index));
		} catch (RuntimeException failure) {
			index.close();
			throw failure;
		}
		try {
			assertTrue(view.centerComplete(survivor),
					"a center that survived the coordinated design retains its complete adjacency");
			assertTrue(view.centerComplete(heavyNonSurvivor),
					"a retained center that failed the design coin must be exact-heavy, hence complete");
			assertFalse(view.centerComplete(absentNonSurvivor),
					"an absent non-survivor may have unretained adjacency and is not complete");
			assertFalse(view.centerComplete(0L), "unbound and unknown centers are never complete");
			assertTrue(directionalCenterComplete(view, 2, survivor),
					"the coordinated design must cover an object center independently of whether it has rows");
			assertTrue(directionalCenterComplete(view, 2, reverseHeavyNonSurvivor),
					"an O2S exact-heavy record must make the reverse adjacency complete");
			assertFalse(directionalCenterComplete(view, 2, heavyNonSurvivor),
					"an S2O exact-heavy record must not make the reverse adjacency complete");
		} finally {
			view.release();
		}
	}

	@Test
	void mappedIndexRetainsReverseDesignAndAuditLanesWithoutMixingExecutionMass(
			@TempDir Path frontierDirectory) throws Exception {
		FrontierPayloadDescriptor descriptor = descriptor();
		FrontierQueryIndex.Builder builder = FrontierQueryIndex.builder(
				frontierDirectory, identity(), descriptor, BUDGET_BYTES, NioFrontierFileOps.INSTANCE);
		builder.accept(1, 1, 0, true, false, 11L, 101L, 21L, 0L, 2.0d, 0.5d, 1L);
		builder.accept(2, 1, 0, true, true, 22L, 102L, 12L, 0L, 1.0d, 1.0d, 2L);
		builder.accept(1, 1, 1, true, false, 13L, 103L, 23L, 0L, 2.0d, 0.5d, 3L);
		builder.accept(1, 2, 0, true, false, 14L, 104L, 24L, 0L, 2.0d, 0.5d, 4L);
		builder.accept(1, 1, 0, false, false, 15L, 105L, 25L, 0L, 2.0d, 0.5d, 5L);

		FrontierQueryIndex index = builder.finish(0.5d, false);
		FrontierQueryIndexView view;
		try {
			view = new FrontierQueryIndexView(identity(), List.of(index));
		} catch (RuntimeException failure) {
			index.close();
			throw failure;
		}
		try {
			assertEquals(4L, index.rowCount(), "every explicit orientation and lane must remain mapped");
			FrontierLeafSelector any = new FrontierLeafSelector(0L, 0L, 0L, 0L, false, 0);
			assertEquals(1L, index.countMatches(any),
					"the execution measure must remain S2O design lane zero");
			assertEquals(1L, scopedCount(index, any, 1, 1, 1));
			assertEquals(1L, scopedCount(index, any, 1, 2, 0));

			FrontierLeafSelector reverseQuad = new FrontierLeafSelector(12L, 102L, 22L, 0L, false, 0);
			assertEquals(1L, scopedCount(index, reverseQuad, 2, 1, 0),
					"an O2S payload record must be exposed in canonical RDF subject/object order");
			assertTrue(exactCenter(index, 2, 1, 0, 22L),
					"the mapped index must retain the record-level exact-heavy flag");
			assertFalse(exactCenter(index, 1, 1, 0, 11L));

			Object diagnostics = laneDiagnostics(view, any, 1);
			assertEquals(2.0d, diagnosticWeight(diagnostics, "designWeightedRows", 0));
			assertEquals(2.0d, diagnosticWeight(diagnostics, "designWeightedRows", 1));
			assertEquals(2.0d, diagnosticWeight(diagnostics, "auditWeightedRows", 0));
			assertEquals(0.0d, diagnosticWeight(diagnostics, "auditWeightedRows", 1));
		} finally {
			view.release();
		}
	}

	@Test
	void predicateOnlyPrimaryVisitUsesPrecomputedLaneDiagnostics(@TempDir Path frontierDirectory) throws Exception {
		FrontierQueryIndex.Builder builder = FrontierQueryIndex.builder(
				frontierDirectory, identity(), descriptor(), BUDGET_BYTES, NioFrontierFileOps.INSTANCE);
		builder.accept(1, 1, 0, true, false, 11L, 101L, 21L, 0L, 2.0d, 0.5d, 1L);
		builder.accept(1, 1, 1, true, false, 12L, 101L, 22L, 0L, 3.0d, 0.5d, 2L);
		builder.accept(1, 2, 0, true, false, 13L, 101L, 23L, 0L, 4.0d, 0.5d, 3L);
		builder.accept(1, 2, 1, true, false, 14L, 101L, 24L, 0L, 5.0d, 0.5d, 4L);

		FrontierQueryIndex index = builder.finish(0.5d, false);
		FrontierQueryIndexView view;
		try {
			view = new FrontierQueryIndexView(identity(), List.of(index));
		} catch (RuntimeException failure) {
			index.close();
			throw failure;
		}
		try (FrontierQueryIndexLease lease = FrontierQueryIndexLease.ready(view)) {
			FrontierLeafSelector predicate = new FrontierLeafSelector(0L, 101L, 0L, 0L, false, 0);
			List<Long> primarySubjects = new ArrayList<>();
			FrontierQueryIndexLeafScan scan = lease.visitPrimaryLeafWithDiagnostics(
					predicate,
					1L,
					(subject, ignoredPredicate, object, context, weight) -> primarySubjects.add(subject));

			assertTrue(scan.complete(),
					"generation-scoped lane summaries must not consume the query-local primary scan budget");
			assertEquals(1L, scan.diagnostics().scannedRows(),
					"the query-local scan must visit design lane zero only");
			assertEquals(List.of(11L), primarySubjects);
			assertEquals(1L, scan.diagnostics().designMatchedRows(0));
			assertEquals(2.0d, scan.diagnostics().designWeightedRows(0));
			assertEquals(1L, scan.diagnostics().designMatchedRows(1));
			assertEquals(3.0d, scan.diagnostics().designWeightedRows(1));
			assertEquals(1L, scan.diagnostics().auditMatchedRows(0));
			assertEquals(4.0d, scan.diagnostics().auditWeightedRows(0));
			assertEquals(1L, scan.diagnostics().auditMatchedRows(1));
			assertEquals(5.0d, scan.diagnostics().auditWeightedRows(1));
		}
	}

	private static long scopedCount(FrontierQueryIndex index, FrontierLeafSelector selector,
			int direction, int laneRole, int laneIndex) {
		try {
			return (long) FrontierQueryIndex.class
					.getDeclaredMethod(
							"countMatches",
							FrontierLeafSelector.class,
							int.class,
							int.class,
							int.class)
					.invoke(index, selector, direction, laneRole, laneIndex);
		} catch (InvocationTargetException failure) {
			if (failure.getCause()instanceof RuntimeException runtimeFailure) {
				throw runtimeFailure;
			}
			if (failure.getCause()instanceof Error error) {
				throw error;
			}
			throw new AssertionError(failure.getCause());
		} catch (ReflectiveOperationException failure) {
			throw new AssertionError(failure);
		}
	}

