	private static long nextCenter(boolean selected, long after, double inclusionProbability) {
		for (long centerId = after + 1L; centerId < after + 10_000L; centerId++) {
			if (FrontierSynopsisBuilder.selected(
					FrontierSynopsisBuilder.laneHash(centerId, 1, 0), inclusionProbability) == selected) {
				return centerId;
			}
		}
		throw new AssertionError("no center id with the requested selection status");
	}

	@Test
	void corruptTruncatedAndWrongSourceIndexesAreRejected(@TempDir Path frontierDirectory) throws Exception {
		FrontierPayloadDescriptor descriptor = descriptor();
		FrontierQueryIndex.Builder builder = FrontierQueryIndex.builder(
				frontierDirectory, identity(), descriptor, BUDGET_BYTES, NioFrontierFileOps.INSTANCE);
		builder.accept(1, 1, 0, true, true, 11L, 101L, 21L, 0L, 1.0d, 1.0d, 0L);
		Path path;
		byte[] valid;
		try (FrontierQueryIndex index = builder.finish(1.0d, true)) {
			path = index.path();
			valid = Files.readAllBytes(path);
		}

		byte[] corrupt = valid.clone();
		corrupt[FrontierQueryIndex.HEADER_BYTES + 3] ^= 0x55;
		Files.write(path, corrupt);
		assertThrows(IOException.class, () -> FrontierQueryIndex.open(
				frontierDirectory, identity(), descriptor, BUDGET_BYTES, NioFrontierFileOps.INSTANCE));

		Files.write(path, Arrays.copyOf(valid, valid.length - 1));
		assertThrows(IOException.class, () -> FrontierQueryIndex.open(
				frontierDirectory, identity(), descriptor, BUDGET_BYTES, NioFrontierFileOps.INSTANCE));

		Files.write(path, valid);
		byte[] otherDigest = descriptor.digest();
		otherDigest[0] ^= 1;
		FrontierPayloadDescriptor otherSource = new FrontierPayloadDescriptor(
				descriptor.kind(), descriptor.generation(), descriptor.byteLength(), otherDigest);
		assertThrows(IOException.class, () -> FrontierQueryIndex.open(
				frontierDirectory, identity(), otherSource, BUDGET_BYTES, NioFrontierFileOps.INSTANCE));
	}

	@Test
	void retainedLeaseSurvivesMappedGenerationReplacement(@TempDir Path frontierDirectory) {
		FrontierSnapshotSourceFactory snapshots = () -> new FixtureSnapshot();
		try (LmdbFrontierSynopsisService service = new LmdbFrontierSynopsisService(
				frontierDirectory,
				FrontierEstimatorMode.AUTHORITATIVE,
				identity(),
				snapshots,
				NioFrontierFileOps.INSTANCE)) {
			assertEquals(FrontierSynopsisStatus.READY, service.rebuild());
			FrontierQueryIndexLease retained = service.acquireQueryIndex(SNAPSHOT_EPOCH);
			assertTrue(retained.ready());
			assertEquals(FrontierSynopsisStatus.READY, service.rebuild());

			FrontierLeafSelector selector = new FrontierLeafSelector(0L, 101L, 0L, 0L, false, 0);
			assertEquals(2L, retained.countMatches(selector));
			try (FrontierQueryIndexLease replacement = service.acquireQueryIndex(SNAPSHOT_EPOCH)) {
				assertTrue(replacement.ready());
				assertEquals(2L, replacement.countMatches(selector));
			}
			retained.close();
			assertFalse(retained.ready());
			retained.close();
		}
	}

